{"policy":"permit (
    principal is User,
    action == Action::"overrideZoneSchedule",
    resource is Zone
)
when {
    principal.roles.contains(Role::"zoneController") &&
    resource.assignedController == principal &&
    principal.controlTier >= resource.criticalityLevel &&
    resource.status != "locked"
};

forbid (
    principal is User,
    action == Action::"overrideZoneSchedule",
    resource is Zone
)
when {
    principal.roles.contains(Role::"maintenanceTechnician") ||
    principal.roles.contains(Role::"tenant")
};"}
